11		"github.com/anthnel/devdesk/internal/engine"
12		"github.com/anthnel/devdesk/internal/netproxy"
13	)
14	
15	// DEVDESK-583, step 3: every `<engine> run --rm` goes through containerRun.cmd,
16	// which adds `-e NAME` for each proxy variable to forward, right before the
17	// image, and puts the values in the child's environment, never in argv. The
18	// argv produced with no proxy is frozen by container_builders_test.go
19	// (TestContainerBuildersWithoutProxyAreUnchanged); this file does not repeat it.
20	
21	const (
22		fwdHTTPValue  = "REDACTED"
23		fwdHTTPSValue = "REDACTED"
24		fwdNoValue    = "internal.example.net,.corp.example.net"
25	)
26	
27	// fwdLeaks is everything that must never appear in an argv or in a displayed
28	// command: the raw values and the pieces a credential or a host is made of.
29	var fwdLeaks = []string{
30		fwdHTTPValue, fwdHTTPSValue, fwdNoValue,
31		"s3cr3tREDACTED", "hunter2REDACTED", "alice-user", "bob-user",
32		"proxy.example.com", "3128", "internal.example.net", "corp.example.net",
33	}
34	
35	// fullProxy is the three pairs, each given in its upper case name only.
36	var fullProxy = map[string]string{
37		"HTTP_PROXY":  fwdHTTPValue,
38		"HTTPS_PROXY": fwdHTTPSValue,
39		"NO_PROXY":    fwdNoValue,
40	}
41	
42	// forwardOf builds a Forward from the variables a process would have.
43	func forwardOf(vars map[string]string) netproxy.Forward {
44		return netproxy.ForwardFromLookup(func(name string) (string, bool) {
45			v, ok := vars[name]
46			return v, ok
47		})
48	}
49	
50	// useProxy swaps the seam for one test and restores it afterwards.
51	func useProxy(t *testing.T, fwd netproxy.Forward) {
52		t.Helper()
53		previous := proxyForward
54		proxyForward = func() netproxy.Forward { return fwd }
55		t.Cleanup(func() { proxyForward = previous })
56	}
57	
58	// forEachEngine runs fn once per engine the scanners can use.
59	func forEachEngine(t *testing.T, fn func(t *testing.T, binary string)) {
60		t.Helper()
61		for _, name := range []string{engine.Docker, engine.Podman} {
62			t.Run(name, func(t *testing.T) {
63				useEngine(t, engine.ShapeFor(name))
64				fn(t, engine.Current().Binary)
65			})
66		}
67	}
68	
69	// pairsOf lists "-e NAME" for each name.
70	func pairsOf(names []string) []string {
71		var out []string
72		for _, n := range names {
73			out = append(out, "-e", n)
74		}
75		return out
76	}
77	
78	// containerImages are the images the cases of containerBuilders run.
79	var containerImages = []string{
80		"aquasec/trivy", "zricethezav/gitleaks", DefaultCosignImage,
81		"registry.example.com/tools/img:1", "getplumber/plumber",
82		"ghcr.io/yannh/kubeconform", "alpine/helm", "registry.k8s.io/kustomize/kustomize:v5.8.1",
83	}
84	
85	// withNamesBeforeImage returns args with the -e pairs of names inserted right
86	// before the image, which is where containerRun.cmd puts them.
87	func withNamesBeforeImage(t *testing.T, args []string, names []string) []string {
88		t.Helper()
89		at := slices.IndexFunc(args, func(a string) bool { return slices.Contains(containerImages, a) })
90		if at < 0 {
91			t.Fatalf("no known image in %q", args)
92		}
93		return slices.Concat(args[:at], pairsOf(names), args[at:])
94	}
95	
96	// checkNoLeak fails when s contains any proxy value or piece of one.
97	func checkNoLeak(t *testing.T, what, s string) {
98		t.Helper()
99		for _, leak := range fwdLeaks {
100			if strings.Contains(s, leak) {
101				t.Errorf("%s contains %q: %s", what, leak, s)
102			}
103		}
104	}
105	
106	// checkProxyEnv fails unless env holds each variable of want exactly once with
107	// its value, and none of the other proxy variables.
108	func checkProxyEnv(t *testing.T, env []string, want map[string]string) {
109		t.Helper()
110		for _, name := range netproxy.ForwardedVariables {
111			var found []string
112			for _, kv := range env {
113				if strings.HasPrefix(kv, name+"=") {
114					found = append(found, kv)
115				}
116			}
117			value, expected := want[name]
118			switch {
119			case !expected && len(found) > 0:
120				t.Errorf("Env carries %q although %s is not forwarded", found, name)
121			case expected && !slices.Equal(found, []string{name + "=" + value}):
122				t.Errorf("Env entries for %s = %q, want exactly %q", name, found, name+"="+value)
123			}
124		}
125	}
126	
127	// bothCasings gives each upper case name of vars its lower case twin.
128	func bothCasings(vars map[string]string) map[string]string {
129		out := map[string]string{}
130		for name, value := range vars {
131			out[name] = value
132			out[strings.ToLower(name)] = value
133		}
134		return out
135	}
