137	func TestContainerRunWithoutProxyAddsNothing(t *testing.T) {
138		useProxy(t, netproxy.Forward{})
139		forEachEngine(t, func(t *testing.T, binary string) {
140			got := containerRun{
141				Flags: []string{"-v", "/repo:/scan:ro", "-w", "/scan"},
142				Image: "img:1",
143				Argv:  []string{"tool", "--flag"},
144				Stdin: []byte("in"),
145			}.cmd()
146			want := []string{"run", "--rm", "-v", "/repo:/scan:ro", "-w", "/scan", "img:1", "tool", "--flag"}
147			if got.Name != binary || !slices.Equal(got.Args, want) {
148				t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
149			}
150			if got.Env != nil {
151				t.Errorf("Env = %q, want nil", got.Env)
152			}
153			if string(got.Stdin) != "in" {
154				t.Errorf("Stdin = %q, want it carried", got.Stdin)
155			}
156		})
157	}
158	
159	func TestContainerRunWithoutProxyKeepsExtraEnvironment(t *testing.T) {
160		useProxy(t, netproxy.Forward{})
161		forEachEngine(t, func(t *testing.T, _ string) {
162			got := containerRun{
163				Flags: []string{"-e", "TOKEN"},
164				Image: "img:1",
165				Env:   []string{"TOKEN=t0k3n"},
166			}.cmd()
167			if want := []string{"run", "--rm", "-e", "TOKEN", "img:1"}; !slices.Equal(got.Args, want) {
168				t.Errorf("Args = %q, want %q", got.Args, want)
169			}
170			if want := slices.Concat(os.Environ(), []string{"TOKEN=t0k3n"}); !slices.Equal(got.Env, want) {
171				t.Errorf("Env = %q, want os.Environ() plus the credential %q", got.Env, want)
172			}
173		})
174	}
175	
176	func TestContainerRunForwardsTheProxyByName(t *testing.T) {
177		fwd := forwardOf(map[string]string{"HTTPS_PROXY": "REDACTED"})
178		useProxy(t, fwd)
179		// A stale value in this process must lose to the forwarded one.
180		t.Setenv("HTTPS_PROXY", "http://stale.example.org:1")
181		forEachEngine(t, func(t *testing.T, binary string) {
182			got := containerRun{
183				Flags: []string{"-v", "/repo:/scan:ro", "-e", "TOKEN"},
184				Image: "img:1",
185				Argv:  []string{"tool"},
186				Env:   []string{"TOKEN=t0k3n"},
187			}.cmd()
188			want := []string{"run", "--rm", "-v", "/repo:/scan:ro", "-e", "TOKEN",
189				"-e", "HTTPS_PROXY", "-e", "https_proxy", "img:1", "tool"}
190			if got.Name != binary || !slices.Equal(got.Args, want) {
191				t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
192			}
193			for _, a := range got.Args {
194				if strings.Contains(a, "REDACTED") || strings.Contains(a, "p:3128") {
195					t.Errorf("argv element %q carries the proxy", a)
196				}
197			}
198			if s := got.String(); strings.Contains(s, "REDACTED") || strings.Contains(s, "p:3128") {
199				t.Errorf("String() carries the proxy: %s", s)
200			}
201			checkProxyEnv(t, got.Env, map[string]string{
202				"HTTPS_PROXY": "REDACTED", "https_proxy": "REDACTED",
203			})
204			// The credentials come after the proxy pairs, and the rest of the
205			// environment is kept.
206			if want := slices.Concat(fwd.Environ(os.Environ()), []string{"TOKEN=t0k3n"}); !slices.Equal(got.Env, want) {
207				t.Errorf("Env =\n  %q\nwant\n  %q", got.Env, want)
208			}
209		})
210	}
211	
212	// TestEveryContainerBuilderForwardsTheProxy runs every launcher of
213	// containerBuilders with the three pairs set: the six -e NAME sit right before
214	// the image, nothing else moves, no value reaches argv or the displayed
215	// command, and the child's environment carries them.
216	func TestEveryContainerBuilderForwardsTheProxy(t *testing.T) {
217		fwd := forwardOf(fullProxy)
218		useProxy(t, fwd)
219		forEachEngine(t, func(t *testing.T, _ string) {
220			for _, tc := range containerBuilders() {
221				t.Run(tc.name, func(t *testing.T) {
222					useProxy(t, netproxy.Forward{})
223					plain := tc.build()
224					useProxy(t, fwd)
225					got := tc.build()
226	
227					if want := withNamesBeforeImage(t, plain.Args, netproxy.ForwardedVariables); !slices.Equal(got.Args, want) {
228						t.Errorf("Args =\n  %q\nwant\n  %q", got.Args, want)
229					}
230					if got.Name != plain.Name || got.Dir != plain.Dir || string(got.Stdin) != string(plain.Stdin) {
231						t.Errorf("Name, Dir or Stdin changed: %q %q %q, was %q %q %q",
232							got.Name, got.Dir, got.Stdin, plain.Name, plain.Dir, plain.Stdin)
233					}
234					for _, a := range got.Args {
235						checkNoLeak(t, "argv element", a)
236					}
237					checkNoLeak(t, "String()", got.String())
238	
239					checkProxyEnv(t, got.Env, bothCasings(fullProxy))
240					if want := slices.Concat(fwd.Environ(os.Environ()), tc.env); !slices.Equal(got.Env, want) {
241						t.Errorf("Env is not the forwarded environment plus the credentials:\n  %q\nwant\n  %q", got.Env, want)
242					}
243				})
244			}
245		})
246	}
