248	// TestContainerBuildersProxyForwardsOnlyTheNamesSet: a pair that is not set is
249	// not passed, and a pair set in one casing is passed in both.
250	func TestContainerBuildersProxyForwardsOnlyTheNamesSet(t *testing.T) {
251		noProxyEnvironment(t) // the case where nothing is forwarded keeps os.Environ() as is
252		cases := []struct {
253			name string
254			vars map[string]string
255			want map[string]string // what the child's environment must hold
256		}{
257			{"NO_PROXY alone", map[string]string{"NO_PROXY": fwdNoValue},
258				map[string]string{"NO_PROXY": fwdNoValue, "no_proxy": fwdNoValue}},
259			{"HTTP_PROXY alone", map[string]string{"HTTP_PROXY": fwdHTTPValue},
260				map[string]string{"HTTP_PROXY": fwdHTTPValue, "http_proxy": fwdHTTPValue}},
261			{"lower case https_proxy alone", map[string]string{"https_proxy": fwdHTTPSValue},
262				map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "https_proxy": fwdHTTPSValue}},
263			{"HTTPS_PROXY and NO_PROXY", map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "NO_PROXY": fwdNoValue},
264				map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "https_proxy": fwdHTTPSValue,
265					"NO_PROXY": fwdNoValue, "no_proxy": fwdNoValue}},
266			{"ALL_PROXY is not read", map[string]string{"ALL_PROXY": fwdHTTPValue, "FTP_PROXY": fwdHTTPValue}, nil},
267		}
268		for _, c := range cases {
269			t.Run(c.name, func(t *testing.T) {
270				fwd := forwardOf(c.vars)
271				forEachEngine(t, func(t *testing.T, _ string) {
272					for _, tc := range containerBuilders() {
273						t.Run(tc.name, func(t *testing.T) {
274							useProxy(t, netproxy.Forward{})
275							plain := tc.build()
276							useProxy(t, fwd)
277							got := tc.build()
278	
279							if want := withNamesBeforeImage(t, plain.Args, fwd.Names()); !slices.Equal(got.Args, want) {
280								t.Errorf("Args =\n  %q\nwant\n  %q", got.Args, want)
281							}
282							for _, a := range got.Args {
283								checkNoLeak(t, "argv element", a)
284							}
285							checkProxyEnv(t, got.Env, c.want)
286						})
287					}
288				})
289			})
290		}
291	}
