293	// TestCosignProxyKeepsRegistryCredentials: the existing -e COSIGN_REGISTRY_*
294	// stay once, in front of the proxy names, with their values after the
295	// forwarded variables in Env.
296	func TestCosignProxyKeepsRegistryCredentials(t *testing.T) {
297		fwd := forwardOf(fullProxy)
298		useProxy(t, fwd)
299		forEachEngine(t, func(t *testing.T, _ string) {
300			checked := 0
301			for _, tc := range containerBuilders() {
302				if !strings.HasPrefix(tc.name, "cosign") || len(tc.env) == 0 {
303					continue
304				}
305				checked++
306				t.Run(tc.name, func(t *testing.T) {
307					got := tc.build()
308					first := slices.Index(got.Args, "HTTP_PROXY")
309					for _, name := range []string{cosignUserEnv, cosignPasswordEnv} {
310						if n := strings.Count(strings.Join(got.Args, " "), name); n != 1 {
311							t.Errorf("%s appears %d times in argv, want once: %q", name, n, got.Args)
312						}
313						at := slices.Index(got.Args, name)
314						if at < 0 || first < 0 || at > first {
315							t.Errorf("%s at %d must come before the proxy names (at %d): %q", name, at, first, got.Args)
316						}
317						if at > 0 && got.Args[at-1] != "-e" {
318							t.Errorf("%s is not passed as -e NAME: %q", name, got.Args)
319						}
320					}
321					for _, kv := range tc.env {
322						if !slices.Contains(got.Env, kv) {
